class RedisSimulado:
    def __init__(self):
        self.sorted_sets = {}
        self.hashes = {}

    def zadd(self, clave, miembro, score):
        self.sorted_sets.setdefault(clave, {})[miembro] = score

    def zrange_desc(self, clave, top):
        items = sorted(self.sorted_sets.get(clave, {}).items(), key=lambda x: x[1], reverse=True)
        return items[:top]

    def hset(self, clave, campo, valor):
        self.hashes.setdefault(clave, {})[campo] = valor

    def hget(self, clave, campo):
        return self.hashes.get(clave, {}).get(campo)

r = RedisSimulado()
r.zadd("ranking", "ana", 950)
r.zadd("ranking", "beto", 1200)
r.zadd("ranking", "carla", 1100)

print("top 2 del ranking:", r.zrange_desc("ranking", 2))

r.hset("perfil:beto", "nivel", "experto")
r.hset("perfil:beto", "puntos", 1200)
r.hset("perfil:beto", "nivel", "maestro")

print("campo actualizado sin tocar el resto:", r.hget("perfil:beto", "nivel"), r.hget("perfil:beto", "puntos"))
